
(function(){
  var SRC="data:image/webp;base64,", ATLAS="data:image/webp;base64,", W=2172, H=724, STEP=2, PAD=70, SIGMA=18, GAZE=58;
  // Sprite iris: [x di atlas, x tujuan, y tujuan, lebar, tinggi]
  var IRIS=[[0,460,286,264,156],[264,1446,286,264,156]];
  var loader=document.getElementById('loader'), zoom=document.getElementById('zoom');
  var cv=document.getElementById('eyes'), ctx=cv.getContext('2d');

  // Garis kelopak mata kiri (koordinat piksel gambar). Mata kanan = cermin.
  var UL=[[250,385],[270,330],[310,305],[360,298],[460,295],[560,298],[660,308],[760,350],[850,415],[872,468]];
  var LL=[[250,385],[290,382],[360,430],[510,452],[660,452],[810,440],[872,468]];
  function mirror(p){return p.map(function(q){return [W-q[0],q[1]]}).sort(function(a,b){return a[0]-b[0]})}
  function interp(p,x){
    if(x<=p[0][0])return p[0][1]; if(x>=p[p.length-1][0])return p[p.length-1][1];
    for(var i=1;i<p.length;i++){ if(x<=p[i][0]){var a=p[i-1],b=p[i];return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])}}
  }
  function build(u,l){
    var x0=u[0][0]-PAD, x1=u[u.length-1][0]+PAD, n=x1-x0+1, up=[],d=[],i,j;
    for(i=0;i<n;i++){var x=x0+i,a=interp(u,x),b=interp(l,x);up.push(Math.round(a));d.push(Math.max(0,b-a))}
    var r=Math.ceil(SIGMA*3),k=[],s=0;
    for(i=-r;i<=r;i++){var v=Math.exp(-i*i/(2*SIGMA*SIGMA));k.push(v);s+=v}
    var sm=[];
    for(i=0;i<n;i++){var acc=0;for(j=-r;j<=r;j++){var q=Math.min(n-1,Math.max(0,i+j));acc+=d[q]*k[j+r]}sm.push(acc/s)}
    var cols=[];
    for(i=0;i<n;i+=STEP)cols.push([x0+i,up[i],sm[i]]);
    return cols;
  }
  var cols=build(UL,LL).concat(build(mirror(UL),mirror(LL)));

  var img=new Image(), atlas=new Image(), st=document.createElement('canvas'), sctx;
  st.width=W; st.height=H; sctx=st.getContext('2d');
  var ready=false, loaded=0;

  // ---- Keadaan animasi ----
  var blinkAnim=null;          // kedipan yang sedang berjalan
  var gaze=0, gazeAuto=0;      // arah pandang -1 (kiri) .. 1 (kanan): saat ini & target otomatis
  var gazePtr=0, lastPtr=-1e9; // target dari pointer (mouse/sentuh)
  var lockCenter=false;        // true saat zoom: bola mata dikunci ke tengah agar tepat ke sorotan cahaya
  var drawn={t:-1,g:1e9}, raf=0, lastNow=0;

  // t: 0 = terbuka, 1 = tertutup. gx: geseran bola mata (piksel gambar), g: arah pandang -1..1
  function drawIris(gx,g){
    var sq=1-0.05*Math.abs(g); // iris sedikit menyempit saat melirik ke samping (efek bulat/3D)
    for(var i=0;i<IRIS.length;i++){
      var q=IRIS[i], dw=q[3]*sq;
      ctx.drawImage(atlas,q[0],0,q[3],q[4],q[1]+gx+(q[3]-dw)/2,q[2],dw,q[4]);
    }
  }
  function draw(t,gx,g){
    var i;
    if(t<=0.001&&gx===0){
      ctx.drawImage(img,0,0);
      drawIris(0,0);
      return;
    }
    ctx.drawImage(st,0,0);
    // bola mata digambar di bawah kelopak atas, jadi kelopak otomatis menutupinya
    drawIris(gx,g);
    for(i=0;i<cols.length;i++){
      var c=cols[i], s=Math.round(c[2]*t);
      ctx.drawImage(img,c[0],0,STEP,c[1],c[0],s,STEP,c[1]);
    }
  }
  function blink(close,hold,open,done){
    blinkAnim={t0:performance.now(),close:close,hold:hold,open:open,done:done};
  }
  function blinkValue(now){
    if(!blinkAnim)return 0;
    var a=blinkAnim, e=Math.max(0,now-a.t0), t;
    if(e<a.close){var p=e/a.close;t=p*p}
    else if(e<a.close+a.hold){t=1}
    else if(e<a.close+a.hold+a.open){var q=(e-a.close-a.hold)/a.open;t=Math.pow(1-q,2.2)}
    else{var d=a.done;blinkAnim=null;t=0;if(d)d()}
    return t;
  }
  // Model gerak mata nyata: lirikan (saccade) itu cepat dan langsung berhenti, tanpa memantul,
  // lalu mata "menetap" (fixation) dengan getaran mikro yang sangat kecil.
  var sacc=null, pending=null, goal=0;
  function minJerk(u){return u*u*u*(10-15*u+6*u*u)}
  function startSaccade(to,now,gentle){
    var d=Math.abs(to-gaze), first=to;
    pending=null;
    // lirikan besar sering sedikit kurang (~8%) lalu dikoreksi lirikan kecil
    if(!gentle&&d>0.5){first=gaze+(to-gaze)*0.92; pending={at:0,to:to}}
    var dd=Math.abs(first-gaze);
    sacc={t0:now,dur:(gentle?170:95)+(gentle?120:115)*dd,from:gaze,to:first};
    if(pending)pending.at=now+sacc.dur+110;
    goal=to;
  }
  function tick(now){
    raf=requestAnimationFrame(tick);
    lastNow=now;
    var t=blinkValue(now);
    var ptrOn=(performance.now()-lastPtr<2200);
    var desired=lockCenter?0:(ptrOn?gazePtr:gazeAuto);
    if(Math.abs(desired-goal)>(ptrOn?0.05:0.001))startSaccade(desired,now,lockCenter);
    if(!sacc&&pending&&now>=pending.at){var pt=pending.to;pending=null;sacc={t0:now,dur:70,from:gaze,to:pt}}
    if(sacc){
      var u=(now-sacc.t0)/sacc.dur;
      if(u>=1){gaze=sacc.to;sacc=null}
      else gaze=sacc.from+(sacc.to-sacc.from)*minJerk(Math.max(0,u));
    }
    // getaran mikro saat menatap (sangat halus), dimatikan saat zoom
    var drift=lockCenter?0:0.016*Math.sin(now/870)+0.010*Math.sin(now/410+1.3);
    var off=(gaze+drift)*GAZE;
    off=lockCenter&&!sacc?Math.round(off):Math.round(off*4)/4;
    if(t!==drawn.t||off!==drawn.g){draw(t,off,gaze);drawn.t=t;drawn.g=off}
  }
  function stopLoop(){cancelAnimationFrame(raf);raf=0}

  // Bola mata mengikuti pointer (mouse / sentuhan) ke kiri-kanan
  // Bola mata mengikuti pointer (mouse / sentuhan) ke kiri-kanan.
  // Getaran kecil tidak dihitung: pointer baru mengambil alih setelah digerakkan cukup jauh.
  var pX=null,pY=null,pAcc=0,pLast=0;
  window.addEventListener('pointermove',function(e){
    if(lockCenter||loader.classList.contains('is-done'))return;
    var n=performance.now();
    if(n-pLast>700)pAcc=0;
    if(pX!==null)pAcc+=Math.abs(e.clientX-pX)+Math.abs(e.clientY-pY);
    pX=e.clientX;pY=e.clientY;pLast=n;
    if(pAcc<70)return;
    gazePtr=Math.max(-1,Math.min(1,(e.clientX/window.innerWidth-.5)*2.2));
    lastPtr=n;
  },{passive:true});

  // Klik / sentuh: mata berkedip cepat (hanya bila tidak sedang berkedip)
  window.addEventListener('pointerdown',function(e){
    if(lockCenter||blinkAnim||loader.classList.contains('is-done'))return;
    var x=(e.clientX/window.innerWidth-.5)*2.2;
    gazePtr=Math.max(-1,Math.min(1,x)); lastPtr=performance.now();
    blink(110,35,240,function(){});
  },{passive:true});

  function wait(ms,fn){setTimeout(fn,ms)}
  var token=0;

  function run(){
    var my=++token;
    if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches){
      loader.className='eye-loader is-done';document.documentElement.style.overflow='';return;
    }
    document.documentElement.style.overflow='hidden';
    loader.className='eye-loader';
    zoom.style.animation='none'; void zoom.offsetWidth; zoom.style.animation='';
    blinkAnim=null; gaze=0; sacc=null; pending=null; goal=0; gazeAuto=0; gazePtr=0; lastPtr=-1e9; lockCenter=false; drawn.t=-1; lastNow=0;
    stopLoop(); raf=requestAnimationFrame(tick);

    // Urutan: kanan, kiri, tengah, kedip, kanan, kiri, tengah, kedip, lalu zoom.
    // Jeda menatap & jarak lirikan dibuat sedikit bervariasi supaya tidak terlihat seperti mesin.
    function rnd(a,b){return a+Math.random()*(b-a)}
    function look(v,hold,next){ gazeAuto=v; wait(hold,function(){ if(my!==token)return; next(); }); }
    function round(amp,next){
      look( amp*rnd(.85,1),  rnd(560,760), function(){
      look(-amp*rnd(.85,1),  rnd(620,820), function(){
      look( 0,               rnd(380,520), function(){
        blink(150,50,320,function(){ if(my!==token)return; wait(rnd(350,500),function(){ if(my!==token)return; next(); }); });
      }); }); });
    }
    function startZoom(){
      lockCenter=true; // bola mata sudah di tengah; kunci agar zoom tepat ke sorotan cahaya
      loader.className='eye-loader is-show is-zoom';
      // satu kedipan saat zoom mendekati mata kanan, lalu memudar
      wait(1000,function(){ if(my!==token)return; blink(160,60,340,function(){}); });
    }
    requestAnimationFrame(function(){
      loader.className='eye-loader is-show';
      wait(900,function(){ if(my!==token)return;
        round(.75,function(){ round(.65,startZoom); });
      });
    });
  }
  zoom.addEventListener('animationend',function(e){
    if(e.target===zoom){loader.className='eye-loader is-done';document.documentElement.style.overflow='';stopLoop()}
  });
  function onLoad(){
    if(++loaded<2)return;
    sctx.drawImage(img,0,0);
    sctx.fillStyle='#fff';
    for(var i=0;i<cols.length;i++)sctx.fillRect(cols[i][0],0,STEP,cols[i][1]);
    ready=true; run();
  }
  img.onload=onLoad; atlas.onload=onLoad;
  img.src=SRC; atlas.src=ATLAS;
})();
